const data = $input.first().json.body || $input.first().json;
const keyword = data.keyword || 'Sans titre';
const sujet = data.sujet || keyword;
const intent = data.intent || 'informationnelle';
const pilier = data.pilier || 'SEO WP';
const objectif = data.objectif || '';
const audience = data.audience || '';
const priority = data.priority || 'C';
const ps = data.publish_score || 0;
const scoreSeo = (data.audit_seo && data.audit_seo.score_seo) || 0;
const scoreConv = (data.audit_conv && data.audit_conv.score_conversion) || 0;
const scoreAuth = (data.audit_auth && data.audit_auth.score_autorite) || 0;
const docId = data.documentId || '';
const docUrl = docId ? `https://docs.google.com/document/d/${docId}/edit` : null;
const generatedAt = data.generated_at || new Date().toISOString().split('T')[0];
const clusterRole = (data.cluster && data.cluster.role) || 'Satellite';
const aiOverview = data.ai_overview === true || data.ai_overview === 'oui';
const optimiseLlm = !!(data.optimise_llm || data.llm_score);

// Normalise la valeur Pilier vers les options Airtable
const pilierMap = {
  'SEO': 'SEO WP', 'seo': 'SEO WP', 'seo wp': 'SEO WP',
  'LMS': 'LMS', 'CRM': 'CRM', 'Performance': 'Performance',
  'Automatisation': 'Automatisation', 'Ecommerce': 'Ecommerce'
};
const pilierNorm = pilierMap[pilier] || pilier;

const fields = {
  'Mot-clé principal': keyword,
  'Sujet': sujet,
  'Type de contenu': clusterRole,
  'Pilier': pilierNorm,
  'Intention': intent,
  'Audience cible': audience,
  'Objectif business': objectif,
  'Score SEO': scoreSeo,
  'Score Conversion': scoreConv,
  'Score Autorité': scoreAuth,
  'Optimisé LLM ?': optimiseLlm,
  'AI Overview': aiOverview,
  'Priorité': priority,
  'Statut': 'Généré ✓',
  'Date création': generatedAt
};
if (docUrl) fields['Lien Google Doc'] = docUrl;

const airtablePayload = {
  performUpsert: { fieldsToMergeOn: ['Mot-clé principal'] },
  records: [{ fields }]
};

return [{ json: { airtablePayload, keyword, ps, priority } }];

const response = $input.first().json;
const prev = $('Code - Map V2 to Airtable').first().json;
const created = (response.createdRecords || []).length;
const updated = (response.updatedRecords || []).length;
const records = response.records || [];
const firstRecord = records[0] || {};
const recordId = firstRecord.id || '';
const action = created > 0 ? 'created' : (updated > 0 ? 'updated' : 'upserted');
return [{ json: {
  success: true,
  action,
  record_id: recordId,
  keyword: prev.keyword,
  publish_score: prev.ps,
  priority: prev.priority,
  created_count: created,
  updated_count: updated
} }];
